      auditCollection: auditCollectionToObject(this.#json.audit_collection),
      analysisSampleCollection: this.#json.analysis_sample_collection,
      analysisCollection_spectrumIdentifcations: arrayToObjectByProperty(this.#analysisCollection_spectrumIdentifications, "spectrumIdentificationListRef"),
